const toggle=document.querySelector('.billing button');let yearly=false;toggle.addEventListener('click',()=>{yearly=!yearly;toggle.classList.toggle('year',yearly);document.querySelectorAll('.amount').forEach(a=>a.textContent=Number(a.dataset[yearly?'year':'month']).toLocaleString('ru-RU'))});const d=document.querySelector('dialog');document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(e.currentTarget.reportValidity()){d.showModal();e.currentTarget.reset()}});d.querySelector('button').addEventListener('click',()=>d.close());
